"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[2716],{2716(e,a,n){n.d(a,{content:()=>t,description:()=>i,keywords:()=>r,title:()=>o});n(5043);var s=n(579);const o="Nueva investigaci\xf3n en RV: la tecnolog\xeda sin pedagog\xeda no basta",i="Un estudio de Frontiers in Virtual Reality sigui\xf3 el uso de RV durante un semestre en neuroanatom\xeda. \xbfEl hallazgo? Los instructores entend\xedan el potencial de la RV pero carec\xedan de conocimiento pedag\xf3gico. Esto es lo que los laboratorios virtuales necesitan para funcionar de verdad.",r=["RV en educaci\xf3n STEM","aprendizaje con realidad virtual","investigaci\xf3n en educaci\xf3n cient\xedfica","andamiaje pedag\xf3gico","laboratorios virtuales","tecnolog\xeda educativa","marco TPACK","motivaci\xf3n estudiantil"],t=(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)("p",{children:"La mayor\xeda de las investigaciones sobre la realidad virtual en la educaci\xf3n analizan r\xe1fagas breves: una intervenci\xf3n de 20 minutos aqu\xed, una sesi\xf3n de una hora all\xe1. Estas instant\xe1neas nos dicen si los estudiantes encuentran atractiva la RV (normalmente s\xed) y si recuerdan el contenido inmediatamente despu\xe9s (normalmente s\xed). Pero \xbfqu\xe9 sucede cuando la RV se convierte en una parte habitual de un curso, semana tras semana, durante todo un semestre?"}),(0,s.jsxs)("p",{children:["Un nuevo estudio publicado en"," ",(0,s.jsx)("a",{href:"https://www.frontiersin.org/journals/virtual-reality/articles/10.3389/frvir.2026.1783834/full",target:"_blank",rel:"noopener noreferrer",children:"Frontiers in Virtual Reality"})," ","(",(0,s.jsx)("a",{href:"https://doi.org/10.3389/frvir.2026.1783834",target:"_blank",rel:"noopener noreferrer",children:"Wu, Klassen & White, 2026"}),") responde a esa pregunta con un estudio etnogr\xe1fico de un semestre completo sobre la RV en la neuroanatom\xeda de pregrado. Los hallazgos son reveladores y, para cualquiera que est\xe9 construyendo o adquiriendo tecnolog\xeda educativa, encierran un mensaje importante: ",(0,s.jsx)("strong",{children:"tener una tecnolog\xeda impresionante no es suficiente"}),"."]}),(0,s.jsx)("h2",{children:"Lo que los investigadores realmente hicieron"}),(0,s.jsx)("p",{children:"A diferencia de los estudios t\xedpicos de RV que miden las puntuaciones de pre-test y post-test tras una sesi\xf3n breve, Wu y sus colegas se integraron en un curso de neuroanatom\xeda de pregrado en una universidad de California durante un semestre entero. Los estudiantes usaron cascos de RV regularmente en sus sesiones de laboratorio para explorar estructuras cerebrales en 3D, rot\xe1ndolas, ampli\xe1ndolas, examinando v\xedas neuronales desde \xe1ngulos imposibles con modelos f\xedsicos o diagramas en 2D."}),(0,s.jsxs)("p",{children:["Los investigadores utilizaron dos marcos te\xf3ricos para analizar lo que observaron. El primero, ",(0,s.jsx)("strong",{children:"TPACK"})," (Conocimiento Tecnol\xf3gico Pedag\xf3gico del Contenido), examina lo que saben los docentes y c\xf3mo integran tecnolog\xeda, pedagog\xeda y materia. El segundo, ",(0,s.jsx)("strong",{children:"EVT"})," (Teor\xeda de la Expectativa-Valor), analiza la motivaci\xf3n estudiantil: \xbfesperan los estudiantes tener \xe9xito? \xbfVen valor en la tarea? \xbfQu\xe9 costes (esfuerzo, frustraci\xf3n, confusi\xf3n) experimentan?"]}),(0,s.jsx)("p",{children:"La combinaci\xf3n es ingeniosa. TPACK nos habla del lado del docente. EVT nos habla del lado del estudiante. Juntos, revelan si la implementaci\xf3n de la RV realmente funciona en la pr\xe1ctica."}),(0,s.jsx)("h2",{children:"El instructor entend\xeda el potencial de la RV. Pero no c\xf3mo ense\xf1ar con ella."}),(0,s.jsxs)("p",{children:["Aqu\xed es donde las cosas se ponen interesantes. El instructor de este estudio ten\xeda un s\xf3lido ",(0,s.jsx)("strong",{children:"Conocimiento Tecnol\xf3gico del Contenido"}),". Entend\xeda por qu\xe9 la RV era buena para la neuroanatom\xeda: la visualizaci\xf3n tridimensional de estructuras cerebrales complejas, la capacidad de manipular y rotar modelos, ver relaciones espaciales que los diagramas planos no pueden transmitir. El ",(0,s.jsx)("em",{children:"qu\xe9"})," de la RV estaba claro."]}),(0,s.jsxs)("p",{children:["Pero el ",(0,s.jsx)("strong",{children:"Conocimiento Pedag\xf3gico Tecnol\xf3gico"})," del instructor era d\xe9bil. Entend\xeda lo que la RV pod\xeda mostrar. No entend\xeda c\xf3mo ense\xf1ar con ella. No hab\xeda una gu\xeda estructurada para los estudiantes sobre c\xf3mo usar el entorno de RV de forma productiva. No hab\xeda actividades de aprendizaje con andamiaje que progresaran de lo simple a lo complejo. La suposici\xf3n parec\xeda ser que la tecnolog\xeda en s\xed misma har\xeda la ense\xf1anza."]}),(0,s.jsx)("p",{children:"Esta brecha, un fuerte CTC pero un d\xe9bil CPT, aparece con frecuencia en la adopci\xf3n de tecnolog\xeda educativa. Los docentes entusiastas ven el potencial de una nueva herramienta. Entienden sus capacidades. Pero traducir esas capacidades en una pedagog\xeda eficaz requiere un tipo de conocimiento diferente, y ese conocimiento a menudo falta."}),(0,s.jsx)("h2",{children:"Los estudiantes se sent\xedan perdidos, frustrados e inseguros de por qu\xe9 hac\xedan esto"}),(0,s.jsx)("p",{children:"La experiencia de los estudiantes reflej\xf3 la brecha de CPT del instructor. Utilizando el marco EVT, los investigadores descubrieron que los estudiantes experimentaron:"}),(0,s.jsxs)("ul",{children:[(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Bajas creencias de expectativa"}),": Los estudiantes no estaban seguros de si pod\xedan tener \xe9xito con la RV ni de c\xf3mo era siquiera el \xe9xito"]}),(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Valor de utilidad poco claro"}),": \xbfPor qu\xe9 usaban RV en lugar de m\xe9todos tradicionales? \xbfC\xf3mo les ayudar\xeda esto como futuros profesionales sanitarios?"]}),(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:'"Coste" elevado'}),": El esfuerzo requerido para aprender el sistema de RV, la carga cognitiva de navegar por una interfaz desconocida y la frustraci\xf3n cuando las cosas no funcionaban como se esperaba"]})]}),(0,s.jsx)("p",{children:"Algunos estudiantes s\xed encontraron atractiva la RV. El valor de inter\xe9s intr\xednseco estaba ah\xed, al menos inicialmente. Pero ese inter\xe9s impulsado por la novedad no pudo superar las frustraciones acumuladas. Cuando los estudiantes no saben por qu\xe9 hacen algo, cuando los criterios de \xe9xito son vagos y cuando la interfaz crea m\xe1s confusi\xf3n que claridad, ni siquiera una tecnolog\xeda impresionante logra generar aprendizaje."}),(0,s.jsxs)("p",{children:["Los investigadores describen un ",(0,s.jsx)("strong",{children:"desajuste entre las suposiciones del instructor y la realidad de los estudiantes"}),". El instructor asumi\xf3 que los estudiantes sabr\xedan intuitivamente c\xf3mo aprender de la RV. Los estudiantes necesitaban mucha m\xe1s orientaci\xf3n de la que recibieron."]}),(0,s.jsx)("h2",{children:"La tecnolog\xeda sin pedagog\xeda es solo hardware caro"}),(0,s.jsx)("p",{children:"Este estudio se suma a un creciente cuerpo de evidencia de que la tecnolog\xeda educativa triunfa o fracasa en funci\xf3n de su dise\xf1o pedag\xf3gico, no de sus capacidades t\xe9cnicas. Puedes tener el hardware de RV m\xe1s sofisticado del mundo. Si los instructores no saben c\xf3mo ense\xf1ar con \xe9l, y si los estudiantes no reciben un andamiaje adecuado, la tecnolog\xeda se convierte en una distracci\xf3n cara en lugar de una herramienta de aprendizaje."}),(0,s.jsxs)("p",{children:["Los investigadores proponen un ",(0,s.jsx)("strong",{children:"marco de integraci\xf3n TPACK-EVT"})," que conecta el conocimiento del instructor con la motivaci\xf3n del estudiante. Cuando los instructores tienen un s\xf3lido Conocimiento Pedag\xf3gico Tecnol\xf3gico, dise\xf1an actividades que ofrecen a los estudiantes expectativas claras (elevando las creencias de expectativa), conexiones expl\xedcitas con objetivos profesionales (elevando el valor de utilidad) y estructuras de apoyo adecuadas (reduciendo el coste percibido). Los dos marcos no son independientes. Lo que saben los docentes determina c\xf3mo los estudiantes experimentan la tecnolog\xeda de aprendizaje."]}),(0,s.jsx)("h2",{children:"C\xf3mo WhimsyLabs aborda la brecha de CPT"}),(0,s.jsx)("p",{children:"Leemos investigaciones como esta y pensamos: por esto exactamente dise\xf1amos WhimsyLabs como lo hicimos. Sab\xedamos desde el principio que dar a las escuelas software de laboratorio virtual no era suficiente. El propio software ten\xeda que incorporar la pedagog\xeda."}),(0,s.jsxs)("p",{children:["Nuestro tutor de IA, ",(0,s.jsx)("strong",{children:"WhimsyCat"}),", existe espec\xedficamente para abordar la brecha de CPT. Los docentes que usan WhimsyLabs no necesitan averiguar c\xf3mo ense\xf1ar con laboratorios virtuales porque el andamiaje est\xe1 integrado en la experiencia. WhimsyCat proporciona orientaci\xf3n en tiempo real a los estudiantes: explicando qu\xe9 hacen y por qu\xe9, anim\xe1ndolos cuando se atascan, haciendo preguntas que desarrollan el pensamiento cient\xedfico y ajust\xe1ndose al ritmo individual y a los niveles de confusi\xf3n."]}),(0,s.jsx)("p",{children:"Esto aborda directamente las preocupaciones de EVT que identific\xf3 el estudio:"}),(0,s.jsxs)("ul",{children:[(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Creencias de expectativa"}),": WhimsyCat les dice a los estudiantes hacia qu\xe9 est\xe1n trabajando y confirma cu\xe1ndo van por buen camino. Los criterios de \xe9xito son expl\xedcitos, no asumidos."]}),(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Valor de utilidad"}),": Los experimentos se conectan con aplicaciones del mundo real. Los estudiantes ven por qu\xe9 importa una t\xe9cnica de pipeteo adecuada. Entienden c\xf3mo la titulaci\xf3n se relaciona con las pruebas farmac\xe9uticas o el monitoreo ambiental."]}),(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Reducci\xf3n del coste"}),": La interfaz est\xe1 basada en navegador, funciona en Chromebooks y no requiere una curva de aprendizaje de cascos de RV. Cuando los estudiantes tienen dificultades, WhimsyCat lo nota y ayuda de inmediato en lugar de dejar que la frustraci\xf3n se acumule."]})]}),(0,s.jsxs)("p",{children:['Tambi\xe9n abordamos el problema del "semestre completo" que destaca el estudio. WhimsyLabs est\xe1 dise\xf1ado para un uso sostenido, no para demostraciones puntuales. Nuestra ',(0,s.jsx)("strong",{children:"evaluaci\xf3n basada en el proceso"})," capta c\xf3mo trabajan los estudiantes a lo largo de m\xfaltiples sesiones, haciendo seguimiento del desarrollo de la t\xe9cnica y del pensamiento experimental con el tiempo. Los docentes obtienen paneles que muestran trayectorias de aprendizaje, no solo instant\xe1neas de una \xfanica sesi\xf3n."]}),(0,s.jsx)("h2",{children:"Pedagog\xeda primero, tecnolog\xeda despu\xe9s"}),(0,s.jsx)("p",{children:"El estudio de Wu refuerza algo en lo que creemos firmemente: la tecnolog\xeda debe servir a la pedagog\xeda, no al rev\xe9s. Es tentador para las escuelas comprar hardware impresionante y asumir que el aprendizaje vendr\xe1 despu\xe9s. Rara vez funciona as\xed."}),(0,s.jsx)("p",{children:"Al evaluar cualquier tecnolog\xeda educativa, hazte estas preguntas:"}),(0,s.jsxs)("ul",{children:[(0,s.jsx)("li",{children:"\xbfEl producto exige que los docentes desarrollen nuevos conocimientos pedag\xf3gicos? \xbfO incorpora esa pedagog\xeda en la experiencia?"}),(0,s.jsx)("li",{children:"\xbfProporciona andamiaje a los estudiantes? \xbfO asume que los estudiantes lo averiguar\xe1n por s\xed solos?"}),(0,s.jsx)("li",{children:"\xbfReduce la carga cognitiva y la frustraci\xf3n? \xbfO a\xf1ade nuevas barreras?"}),(0,s.jsx)("li",{children:"\xbfPuede usarse de forma sostenible a lo largo de un trimestre o un a\xf1o? \xbfO es una novedad que se desvanece?"})]}),(0,s.jsx)("p",{children:"La RV y otras tecnolog\xedas inmersivas tienen un potencial genuino para la educaci\xf3n cient\xedfica. La visualizaci\xf3n tridimensional de estructuras moleculares, sistemas anat\xf3micos y conceptos de f\xedsica ofrece ventajas que las pantallas planas no pueden igualar. Pero ese potencial solo se convierte en aprendizaje real cuando la tecnolog\xeda va envuelta en un dise\xf1o pedag\xf3gico bien pensado."}),(0,s.jsx)("h2",{children:"De la investigaci\xf3n a la pr\xe1ctica"}),(0,s.jsx)("p",{children:'Estudios como este son valiosos porque van m\xe1s all\xe1 de "\xbffunciona la RV?" hacia "\xbfc\xf3mo y por qu\xe9 funciona o fracasa la RV?" Los estudios de intervenci\xf3n a corto plazo tienen su lugar, pero pasan por alto las complejidades que emergen con el uso sostenido. Los estudiantes pueden tolerar la confusi\xf3n durante 30 minutos. Cuando la confusi\xf3n persiste durante semanas, socava la motivaci\xf3n y el aprendizaje.'}),(0,s.jsx)("p",{children:"Para los educadores y administradores que consideran software de laboratorio virtual, esta investigaci\xf3n ofrece una advertencia clara: no asumas que una tecnolog\xeda sofisticada produce autom\xe1ticamente un aprendizaje sofisticado. Pregunta a los proveedores c\xf3mo apoyan sus productos a los docentes desde el punto de vista pedag\xf3gico. Pregunta c\xf3mo dan andamiaje a la experiencia del estudiante. Pregunta qu\xe9 sucede cuando los estudiantes se atascan o se confunden."}),(0,s.jsx)("p",{children:"En WhimsyLabs, dise\xf1amos para exactamente estos desaf\xedos. WhimsyCat no es decoraci\xf3n. Es el andamiaje pedag\xf3gico que el estudio de Wu demuestra que es esencial. La evaluaci\xf3n basada en el proceso no es marketing. Es la forma en que sostienes un aprendizaje significativo a lo largo de todo un trimestre acad\xe9mico en lugar de solo una demostraci\xf3n llamativa."}),(0,s.jsx)("p",{children:"La tecnolog\xeda puede transformar la educaci\xf3n cient\xedfica. Pero solo cuando viene acompa\xf1ada de la pedagog\xeda adecuada."}),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)("h2",{children:"Art\xedculos relacionados"}),(0,s.jsxs)("ul",{children:[(0,s.jsx)("li",{children:(0,s.jsx)("a",{href:"/es/blog/oecd-ai-learning-paradox-virtual-labs",children:"La paradoja del aprendizaje con IA de la OCDE: por qu\xe9 la IA generativa falla a los estudiantes (y c\xf3mo los laboratorios virtuales triunfan)"})}),(0,s.jsx)("li",{children:(0,s.jsx)("a",{href:"/es/blog/edtech-critics-right-passive-learning-vs-active-labs",children:"Los cr\xedticos tienen raz\xf3n: la mayor\xeda de la EdTech es in\xfatil"})}),(0,s.jsx)("li",{children:(0,s.jsx)("a",{href:"/es/blog/ai-science-tutor-classroom-what-works",children:"Tutores de IA para ciencias: qu\xe9 funciona realmente en el aula"})})]})]}),(0,s.jsxs)("div",{className:"references-section",children:[(0,s.jsx)("h3",{children:"Referencias"}),(0,s.jsxs)("ul",{className:"references-list",children:[(0,s.jsxs)("li",{children:["Wu, X., Klassen, A., & White, T. (2026). Understanding extended VR use in undergraduate STEM education: a focused ethnographic case study of neuroanatomy instruction."," ",(0,s.jsx)("em",{children:"Frontiers in Virtual Reality"}),"."," ",(0,s.jsx)("a",{href:"https://doi.org/10.3389/frvir.2026.1783834",target:"_blank",rel:"noopener noreferrer",children:"https://doi.org/10.3389/frvir.2026.1783834"})]},"ref-1"),(0,s.jsxs)("li",{children:["Mishra, P., & Koehler, M. J. (2006). Technological pedagogical content knowledge: A framework for teacher knowledge."," ",(0,s.jsx)("em",{children:"Teachers College Record, 108"}),"(6), 1017-1054."]},"ref-2"),(0,s.jsxs)("li",{children:["Eccles, J. S., & Wigfield, A. (2002). Motivational beliefs, values, and goals."," ",(0,s.jsx)("em",{children:"Annual Review of Psychology, 53"}),"(1), 109-132."]},"ref-3")]})]})]})}}]);
